import sqlite3
import subprocess
from datetime import datetime, timezone
from typing import Optional
TRACKER_DATABASE_PATH = 'project_tracker.db'
SPRINT_MANAGER_ROLE_NAME = 'sprint_manager'
SPRINT_CONTRIBUTOR_ROLE_NAME = 'contributor'
SPRINT_BOARD_REBUILD_SCRIPT = 'scripts/rebuild_sprint_board.py'

def _upsert_sprint_role(database_cursor, sprint_id, user_id, role_name):
    database_cursor.execute('INSERT INTO sprint_roles (sprint_id, user_id, role) VALUES (?, ?, ?) ON CONFLICT(sprint_id, user_id) DO UPDATE SET role = excluded.role', (sprint_id, user_id, role_name))

def transfer_sprint_ownership(sprint_id: int, new_owner_user_id: int, demote_previous_owner: bool=False, handover_note: Optional[str]=None) -> dict:
    database_connection = sqlite3.connect(TRACKER_DATABASE_PATH)
    try:
        database_cursor = database_connection.cursor()
        sprint_record = database_cursor.execute('SELECT name, owner_user_id FROM sprints WHERE id = ?', (sprint_id,)).fetchone()
        if sprint_record is None:
            return {'success': False, 'error': f'Sprint {sprint_id} not found'}
        sprint_display_name, previous_owner_user_id = sprint_record
        if previous_owner_user_id == new_owner_user_id:
            return {'success': False, 'error': 'User already owns this sprint'}
        new_owner_record = database_cursor.execute('SELECT display_name, is_active FROM users WHERE id = ?', (new_owner_user_id,)).fetchone()
        if new_owner_record is None or not new_owner_record[1]:
            return {'success': False, 'error': f'User {new_owner_user_id} is missing or inactive'}
        new_owner_display_name = new_owner_record[0]
        handover_timestamp = datetime.now(timezone.utc).isoformat()
        database_cursor.execute('UPDATE sprints SET owner_user_id = ?, updated_at = ? WHERE id = ?', (new_owner_user_id, handover_timestamp, sprint_id))
        _upsert_sprint_role(database_cursor, sprint_id, new_owner_user_id, SPRINT_MANAGER_ROLE_NAME)
        previous_owner_resulting_role = SPRINT_MANAGER_ROLE_NAME
        if demote_previous_owner and previous_owner_user_id is not None:
            _upsert_sprint_role(database_cursor, sprint_id, previous_owner_user_id, SPRINT_CONTRIBUTOR_ROLE_NAME)
            previous_owner_resulting_role = SPRINT_CONTRIBUTOR_ROLE_NAME
        database_cursor.execute("INSERT INTO sprint_history (sprint_id, event_type, actor_user_id, details, created_at) VALUES (?, 'ownership_transfer', ?, ?, ?)", (sprint_id, new_owner_user_id, handover_note or f'Ownership moved from user {previous_owner_user_id} to {new_owner_user_id}', handover_timestamp))
        database_connection.commit()
        # Regenerate the cached sprint board so the new owner shows up immediately
        try:
            board_rebuild_result = subprocess.run(['python', SPRINT_BOARD_REBUILD_SCRIPT, '--sprint-id', str(sprint_id), '--db', TRACKER_DATABASE_PATH], capture_output=True, text=True, timeout=60)
            board_rebuilt = board_rebuild_result.returncode == 0
        except (OSError, subprocess.TimeoutExpired):
            board_rebuilt = False
        return {'success': True, 'sprint_id': sprint_id, 'sprint_name': sprint_display_name, 'previous_owner_user_id': previous_owner_user_id, 'previous_owner_role': previous_owner_resulting_role if previous_owner_user_id else None, 'new_owner_user_id': new_owner_user_id, 'new_owner_name': new_owner_display_name, 'transferred_at': handover_timestamp, 'board_rebuilt': board_rebuilt}
    except sqlite3.Error as database_error:
        database_connection.rollback()
        return {'success': False, 'error': str(database_error)}
    finally:
        database_connection.close()
